using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using TransPort.Web.Models;using TransPort.Web.Services;
namespace TransPort.Web.Areas.Gestion.Controllers;
[Area("Gestion"),Authorize(Roles="AdministradorGeneral,Gerente,Empleado,Operativo"),Route("gestion/construcciones")]
public sealed class ConstruccionesController(ITransportApiClient api):Controller
{[HttpGet("")]public async Task<IActionResult>Index(string?estado,int?sedeId,string?busqueda,CancellationToken ct)=>View(new ConstruccionPaginaViewModel{Estado=estado,SedeId=sedeId,Busqueda=busqueda,Proyectos=await api.ConstruccionesAsync(estado,sedeId,busqueda,ct),Opciones=await api.ConstruccionOpcionesAsync(ct)});[HttpPost("crear")]public async Task<IActionResult>Crear(ConstruccionCrearViewModel m,CancellationToken ct){var id=await api.CrearConstruccionAsync(m,ct);return RedirectToAction(nameof(Detalle),new{id});}[HttpGet("{id:long}")]public async Task<IActionResult>Detalle(long id,CancellationToken ct){var x=await api.ConstruccionAsync(id,ct);if(x is null)return NotFound();ViewBag.Opciones=await api.ConstruccionOpcionesAsync(ct);return View(x);}[HttpPost("{id:long}/actividades")]public async Task<IActionResult>Actividad(long id,ConstruccionActividadCrearViewModel m,CancellationToken ct){await api.CrearActividadConstruccionAsync(id,m,ct);return RedirectToAction(nameof(Detalle),new{id});}[HttpPost("{id:long}/actividades/{actividadId:long}/avance")]public async Task<IActionResult>Avance(long id,long actividadId,decimal porcentaje,string comentario,string?evidenciaUrl,CancellationToken ct){await api.RegistrarAvanceConstruccionAsync(actividadId,porcentaje,comentario,evidenciaUrl,ct);return RedirectToAction(nameof(Detalle),new{id});}[HttpPost("{id:long}/recursos")]public async Task<IActionResult>Recurso(long id,ConstruccionRecursoCrearViewModel m,CancellationToken ct){await api.AsignarRecursoConstruccionAsync(id,m,ct);return RedirectToAction(nameof(Detalle),new{id});}[HttpPost("{id:long}/estado")]public async Task<IActionResult>Estado(long id,string estado,CancellationToken ct){await api.EstadoConstruccionAsync(id,estado,ct);return RedirectToAction(nameof(Detalle),new{id});}[HttpPost("{id:long}/eliminar"),Authorize(Roles="AdministradorGeneral")]public async Task<IActionResult>Eliminar(long id,CancellationToken ct){await api.EliminarConstruccionAsync(id,ct);return RedirectToAction(nameof(Index));}}
